require_once __DIR__.'/../auth_check.php';require_once __DIR__.'/model/Database.php';require_once __DIR__.'/../services/DisbursementDocumentComplianceService.php';$pdo=Database::getConnection();$service=new DisbursementDocumentComplianceService($pdo);$uid=(int)($_SESSION['user_id']??0);if(empty($_SESSION['doc_completion_csrf']))$_SESSION['doc_completion_csrf']=bin2hex(random_bytes(32));$flash='';
